class Solution:
    def minimumLevels(self, possible: List[int]) -> int:
        n = len(possible)
        total = sum(1 if x else -1 for x in possible)
        pre = [0] * n
        s = 0
        for i in range(n):
            s += 1 if possible[i] else -1
            pre[i] = s
        for k in range(n - 1):
            if 2 * pre[k] > total:
                return k + 1
        return -1

