class Solution {
public:
    int minimumLevels(vector<int>& possible) {
        int n = possible.size(), total = 0;
        vector<int> pre(n);
        for (int i = 0; i < n; i++) {
            total += possible[i] ? 1 : -1;
            pre[i] = total;
        }
        for (int k = 0; k + 1 < n; k++)
            if (2 * pre[k] > total) return k + 1;
        return -1;
    }
};

